+    const u64 table_base = (u64(cs.user_data[8]) | (u64(cs.user_data[9]) << 32)) &
+                           MaxGuestPointer;
+    const u64 mask_base = (u64(cs.user_data[2]) | (u64(cs.user_data[3]) << 32)) &
+                          MaxGuestPointer;
+    struct TableLayout {
+        const char* label;
+        u32 stride_bytes;
+        u32 image_offset_bytes;
+        u32 mask_offset_dw;
+        u32 bound_offset_dw;
+    };
+    constexpr TableLayout layouts[] = {{"A", 776, 544, 5899, 0}, {"B", 264, 3536, 5900, 1}};
